{
  "stepId": "purchase",
  "description": "Purchase one product. Server-side fulfil-purchase runs before the 201 response; readiness requires reservation, matching captured payment and issued license evidence.",
  "operationId": "$sourceDescriptions.coordinator.purchaseProduct",
  "parameters": [
    {
      "name": "Authorization",
      "in": "header",
      "value": "Bearer {$inputs.clientToken}"
    },
    {
      "name": "Idempotency-Key",
      "in": "header",
      "value": "$inputs.purchaseKey"
    }
  ],
  "requestBody": {
    "contentType": "application/json",
    "payload": {
      "customerId": "$inputs.customerId",
      "productId": "$inputs.productId",
      "amountMinor": "$inputs.amountMinor",
      "currency": "$inputs.currency",
      "paymentToken": "$inputs.paymentToken"
    }
  },
  "successCriteria": [
    {
      "condition": "$statusCode == 201"
    },
    {
      "condition": "$response.body#/state == 'READY'"
    }
  ],
  "outputs": {
    "purchaseId": "$response.body#/purchaseId",
    "licenseId": "$response.body#/licenseId"
  },
  "x-example-actor": "client",
  "x-example-target": "coordinator",
  "x-example-implementation": {
    "workflowId": "fulfil-purchase",
    "timing": "before-response",
    "inputs": {
      "customerId": "$request.body#/customerId",
      "productId": "$request.body#/productId",
      "amountMinor": "$request.body#/amountMinor",
      "currency": "$request.body#/currency",
      "paymentToken": "$request.body#/paymentToken"
    },
    "serverInputs": {
      "purchaseId": "Generated once and durably associated with the scoped purchase key.",
      "serviceToken": "Coordinator service identity from server configuration."
    },
    "response": {
      "purchaseId": "$workflows.fulfil-purchase.outputs.purchaseId",
      "licenseId": "$workflows.fulfil-purchase.outputs.licenseId",
      "state": "$workflows.fulfil-purchase.outputs.state"
    }
  }
}

{
  "stepId": "reserve-and-pay",
  "description": "Obtain matching reservation and confirmed payment before license issuance.",
  "workflowId": "reserve-and-capture",
  "parameters": [
    {
      "name": "purchaseId",
      "value": "$inputs.purchaseId"
    },
    {
      "name": "productId",
      "value": "$inputs.productId"
    },
    {
      "name": "amountMinor",
      "value": "$inputs.amountMinor"
    },
    {
      "name": "currency",
      "value": "$inputs.currency"
    },
    {
      "name": "paymentToken",
      "value": "$inputs.paymentToken"
    },
    {
      "name": "serviceToken",
      "value": "$inputs.serviceToken"
    }
  ],
  "outputs": {
    "reservationId": "$workflows.reserve-and-capture.outputs.reservationId",
    "paymentId": "$workflows.reserve-and-capture.outputs.paymentId",
    "paymentState": "$workflows.reserve-and-capture.outputs.paymentState"
  },
  "successCriteria": [
    {
      "condition": "$workflows.reserve-and-capture.outputs.paymentState == 'CAPTURED'"
    }
  ]
}

{
  "stepId": "reserve-product",
  "description": "Reserve one unit at its current price; verify product, amount and currency.",
  "operationId": "$sourceDescriptions.inventory.reserveProduct",
  "parameters": [
    {
      "name": "Authorization",
      "in": "header",
      "value": "Bearer {$inputs.serviceToken}"
    },
    {
      "name": "Idempotency-Key",
      "in": "header",
      "value": "{$inputs.purchaseId}-reservation"
    }
  ],
  "requestBody": {
    "contentType": "application/json",
    "payload": {
      "productId": "$inputs.productId",
      "quantity": 1
    }
  },
  "successCriteria": [
    {
      "condition": "$statusCode == 201"
    },
    {
      "condition": "$response.body#/state == 'RESERVED'"
    },
    {
      "condition": "$response.body#/productId == $inputs.productId"
    },
    {
      "condition": "$response.body#/amountMinor == $inputs.amountMinor"
    },
    {
      "condition": "$response.body#/currency == $inputs.currency"
    }
  ],
  "outputs": {
    "reservationId": "$response.body#/reservationId",
    "amountMinor": "$response.body#/amountMinor",
    "currency": "$response.body#/currency"
  },
  "x-example-actor": "coordinator",
  "x-example-target": "inventory"
}

{
  "stepId": "persist-verified-purchase-with-structured-policy-and-long-authored-name",
  "workflowId": "record-ready",
  "parameters": [
    {
      "name": "purchaseId",
      "value": "$inputs.purchaseId"
    },
    {
      "name": "licenseId",
      "value": "$inputs.licenseId"
    },
    {
      "name": "serviceToken",
      "value": "$inputs.serviceToken"
    },
    {
      "name": "context",
      "value": "$inputs.context"
    }
  ],
  "x-example-heavy-metadata": {
    "debug": false,
    "retryBudget": 0,
    "fallback": null,
    "emptyString": "",
    "tags": [
      "stress",
      "long-labels",
      "metadata"
    ],
    "policy": {
      "originalKeyRequired": true,
      "authorizedAmount": {
        "minor": 1299,
        "currency": "EUR"
      },
      "reconciliation": {
        "readOriginal": true,
        "replayNewKey": false
      }
    },
    "explanation": "This deliberately lengthy authored note contains \"quotes\", [brackets], semicolons; a literal {$inputs.productId} and a newline\nso that shortening diagram labels does not discard the inspectable source content."
  }
}
